def max_Product(arr):
    """
    Finds and returns the pair of integers in the array that yields the highest product.

    :param arr: List of integers
    :return: Tuple of two integers with the highest product
    """
    if len(arr) < 2:
        raise ValueError("Array should have at least two elements")

    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return (max1, max2) if max1 * max2 > min1 * min2 else (min1, min2)
